DO $$
DECLARE r record; v_rows bigint; v_count bigint; v_t timestamptz; v_n int := 0;
BEGIN
  PERFORM set_config('search_path', 'opera, public', true);
  FOR r IN
    SELECT p.business_unit, p.settlement_date, p.published_run_id, rr.resolved_settlement_date
    FROM opera.recon_snapshot_pointer p
    JOIN opera.recon_refresh_run rr ON rr.uuid = p.published_run_id
    WHERE p.tenant_id = '227cd5f5-4498-4dba-bda9-05b8edc41113' AND p.view_type = 'SETTLE_PRICING'
      AND p.settlement_date = (SELECT max(p2.settlement_date) FROM opera.recon_snapshot_pointer p2
                               WHERE p2.tenant_id = p.tenant_id AND p2.business_unit = p.business_unit AND p2.view_type = p.view_type)
      AND EXISTS (SELECT 1 FROM opera.latest_active_lot_reconcile_log l
                  WHERE l.tenant_id = p.tenant_id AND l.business_unit = p.business_unit AND l.repaired AND (l.missing + l.extra + l.different) > 0
                    AND l.run_at > greatest(rr.completed_at, rr.updated_timestamp))
    ORDER BY p.business_unit
  LOOP
    IF NOT pg_try_advisory_xact_lock(hashtextextended('227cd5f5-4498-4dba-bda9-05b8edc41113' || '|' || r.business_unit || '|SETTLE_PRICING|' || r.resolved_settlement_date::text, 0)) THEN
      RAISE EXCEPTION 'the app is refreshing % SETTLE_PRICING for %: try again later', r.business_unit, r.settlement_date;
    END IF;
    v_t := clock_timestamp();
    v_rows := opera.recon_materialize_settle(r.published_run_id);
    PERFORM opera.recon_postprocess_settle(r.published_run_id);
    SELECT count(*) INTO v_count FROM opera.recon_settle_snapshot
     WHERE run_id = r.published_run_id AND tenant_id = '227cd5f5-4498-4dba-bda9-05b8edc41113' AND business_unit = r.business_unit AND settlement_date = r.resolved_settlement_date;
    IF v_rows IS DISTINCT FROM v_count THEN
      RAISE EXCEPTION 'validation failed for % SETTLE_PRICING: materialised %, persisted %', r.business_unit, v_rows, v_count;
    END IF;
    UPDATE opera.recon_refresh_run SET row_count = v_rows, updated_timestamp = now() WHERE uuid = r.published_run_id;
    v_n := v_n + 1;
    RAISE NOTICE '% SETTLE_PRICING %: % rows in % s', r.business_unit, r.settlement_date, v_rows, round(extract(epoch FROM clock_timestamp() - v_t)::numeric, 1);
  END LOOP;
  RAISE NOTICE 'SETTLE_PRICING: % snapshot(s) rebuilt', v_n;
END $$

